"""/**
 * Whether `actor` may see `project`. Private projects are visible only to
 * owners and admins, platform staff, the project lead and explicit project
 * members; `org` and `public` projects are visible to everyone in the org.
 */
export async function canViewProject(
  actor: Actor,
  project: Project,
): Promise<boolean> {
  if (actor.orgId !== project.orgId) return false;
  if (project.visibility !== "private") return true;
  if (actor.isPlatformStaff === true) return true;
  if (hasRoleAtLeast(actor.role, "admin")) return true;
  if (project.leadId === actor.userId) return true;

  return projectMemberRepo.isProjectMember(
    project.orgId,
    project.id,
    actor.userId,
  );
}

/**
 * Loads a project and throws `NotFoundError` when the actor may not see it,
 * so a private project is indistinguishable from one that does not exist.
 * Every service that touches a project or anything under it goes through here.
 */
export async function requireVisibleProject(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<Project> {
  const project = requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
  if (!(await canViewProject(actor, project))) {
    throw new NotFoundError("Project", projectId);
  }
  return project;
}

