  actor: Actor,
): Promise<readonly ProjectId[]> {
  if (actor.isPlatformStaff === true) return [];
  if (hasRoleAtLeast(actor.role, "admin")) return [];
  return projectRepo.listHiddenProjectIds(actor.orgId, actor.userId);
}

